class Solution {
public:
    int clumsy(int n) {
        stack<int> st;
        st.push(n);
        for (int x = n - 1, op = 0; x >= 1; --x, op = (op + 1) % 4) {
            if (op == 0) { int v = st.top(); st.pop(); st.push(v * x); }
            else if (op == 1) { int v = st.top(); st.pop(); st.push(v / x); }
            else if (op == 2) st.push(x);
            else st.push(-x);
        }
        int result = 0;
        while (!st.empty()) { result += st.top(); st.pop(); }
        return result;
    }
};
